#include <iostream>
#include <memory>
#include <vector>

class Shape {                                    // abstract interface.
public:
    virtual ~Shape() = default;                  // safe deletion through Shape*.
    virtual void draw() const = 0;               // pure virtual.
};

class Circle : public Shape {
public:
    void draw() const override { std::cout << "circle\n"; }
};

class Square : public Shape {
public:
    void draw() const override { std::cout << "square\n"; }
    // void draw() override {}   // error with override: missing const, not an override.
};

int main() {
    std::vector<std::unique_ptr<Shape>> shapes;
    shapes.push_back(std::make_unique<Circle>());
    shapes.push_back(std::make_unique<Square>());
    for (const auto& s : shapes) s->draw();      // circle, square: chosen at run time.
    // Shape s;   error: abstract class.
}                                                // ~Circle and ~Square run via ~Shape.
```

| Piece | Purpose |
|---|---|
| `virtual`. | dispatch on dynamic type. |
| `override`. | compiler checks it really overrides. |
| `= 0`. | must be overridden; class is abstract. |
| `virtual ~Base()`. | correct destruction through base pointers. |

